pred_cypher:
MATCH (p:Player)-[:playsPosition]->(pos:Position)
WHERE EXISTS {
  MATCH (p)-[:playsPosition]->(pf:Position {name: "power forward"})
}
RETURN pos.name, count(DISTINCT p) AS player_count
ORDER BY player_count DESC

MATCH (p:Player)-[:receivesAward]->(a:Award)
WHERE EXISTS {
  MATCH (p)-[:receivesAward]->(la:Award {name: "L'Équipe Champion of Champions"})
}
RETURN a.name, count(DISTINCT p) AS player_count
